// 품목설명 원문 — 기술평가 신청 화면의 [품목설명] 모달이 보여 주는 240개 품목의 설명이다.
// 발주처가 준 원문(품목설명_전체.txt)을 그대로 옮겼고, 문장은 손대지 않았다.
//
// 줄 종류(kind) — 원문의 줄머리 기호를 그대로 옮긴 것이다. 화면에서 어떤 마커·글자로 그릴지는
// composite/item-description-dialog 가 정한다.
//   paragraph  원문 ▣    품목 설명의 본문 한 덩이
//   bullet     원문 -    바로 위 본문에 딸린 세부 항목
//   example    원문 (예시)·(활용 예시) 등으로 시작하는 줄
//   note       원문 *·** ·※ 로 시작하는 용어 풀이·유의사항
//   text       위 어디에도 없는 줄 — 앞줄(주로 예시)에서 이어지는 문장이다
//
// [원문 그대로 둔 것] 일부 줄머리 기호와 문장 속 글자가 물음표로 깨져 있다(원문 변환 단계에서 생긴 것).
// 줄머리의 물음표는 세부 항목(bullet)으로 옮겼고, 문장 속 물음표는 무엇이었는지 알 수 없어 그대로 둔다.
//
// [연동 시] 이 목록이 API 로 내려오면 이 파일을 지우고 같은 모양의 데이터를 넣으면 화면은 그대로 쓴다.

type ItemDescriptionLineKind = 'paragraph' | 'bullet' | 'example' | 'note' | 'text'

type ItemDescriptionLine = {
    kind: ItemDescriptionLineKind
    text: string
}

type ItemDescription = {
    // 원문의 항목 번호([1]~[240]).
    no: number
    name: string
    lines: readonly ItemDescriptionLine[]
}

const ITEM_DESCRIPTION_TITLE = '품목설명'
const ITEM_DESCRIPTION_GUIDE = '신청할 품목의 정의와 예시를 확인할 수 있습니다.'

